(cherry picked from commit 714ee6754ac5fa3dc078856a196a6b124cd797a0)
Signed-off-by: Rodrigo Vivi <rodrigo.vivi@intel.com>

Here is the root cause:
The page fault handler (xe_pagefault_service) did not verify that the VMA is not read-only before allowing write or atomic access. This allowed writes to read-only memory regions.

Here is the patch:

 static int xe_pagefault_service(struct xe_pagefault *pf)
 {
 	struct xe_gt *gt = pf->gt;
 	struct xe_device *xe = gt_to_xe(gt);
 	struct xe_vm *vm;
 	struct xe_vma *vma = NULL;
 	int err;
 	bool atomic;

 	/* Producer flagged this fault to be nacked */
 	if (pf->consumer.fault_level == XE_PAGEFAULT_LEVEL_NACK)
 		return -EFAULT;

 	vm = xe_pagefault_asid_to_vm(xe, pf->consumer.asid);
 	if (IS_ERR(vm))
 		return PTR_ERR(vm);

 	/*
 	 * TODO: Change to read lock? Using write lock for simplicity.
 	 */
 	down_write(&vm->lock);

 	if (xe_vm_is_closed(vm)) {
 		err = -ENOENT;
 		goto unlock_vm;
 	}

 	vma = xe_vm_find_vma_by_addr(vm, pf->consumer.page_addr);
 	if (!vma) {
 		err = -EINVAL;
 		goto unlock_vm;
 	}

+	if (xe_vma_read_only(vma) &&
+	    pf->consumer.access_type != XE_PAGEFAULT_ACCESS_TYPE_READ) {
+		err = -EPERM;
+		goto unlock_vm;
+	}
+
 	atomic = xe_pagefault_access_is_atomic(pf->consumer.access_type);

 	if (xe_vma_is_cpu_addr_mirror(vma))
 		err = xe_svm_handle_pagefault(vm, vma, gt,
 					      pf->consumer.page_addr, atomic);
 	else
 		err = xe_pagefault_handle_vma(gt, vma, atomic);

 unlock_vm:
 	if (!err)
 		vm->usm.last_fault_vma = vma;
 	up_write(&vm->lock);
 	xe_vm_put(vm);

 	return err;
 }



